import json, os, collections
from pathlib import Path
root=Path("/Users/ramil/Documents/WORK")
files=list(root.rglob("планфикс/*.json"))
print("files", len(files))
statuses=collections.Counter()
names=[]
assignees=collections.Counter()
n=0
for fp in files:
    try:
        data=json.loads(fp.read_text())
    except Exception as e:
        print("fail", fp, e)
        continue
    if not isinstance(data, dict):
        continue
    for k,v in data.items():
        if not isinstance(v, dict) or "task" not in v:
            continue
        t=v["task"]
        if not isinstance(t, dict) or "status" not in t:
            continue
        n+=1
        st=t.get("status") or {}
        statuses[st.get("name")] += 1
        names.append((t.get("id"), st.get("name"), (t.get("name") or "")[:80], fp.parent.parent.name))
        users=(t.get("assignees") or {}).get("users") or []
        for u in users:
            if isinstance(u, dict):
                assignees[u.get("name")] += 1
print("tasks", n)
print("STATUSES")
for k,v in statuses.most_common():
    print(f"  {v:4} {k}")
print("ASSIGNEES")
for k,v in assignees.most_common():
    print(f"  {v:4} {k}")
print("--- sample names ---")
for row in names[:40]:
    print(row)
