def classify(sender, subject):
    s=(sender or "").lower()
    dom=s.split("@")[-1] if "@" in s else s
    sub=(subject or "").lower()
    # internal echoes
    if "остатки товаров" in sub or "задолженность покупателей" in sub:
        return "внутренний отчёт"
    if s.endswith("@tonaly.ru") or s in ("ooo.tonal@mail.ru","ooo.tonaly@mail.ru"):
        if sub.startswith("счет") or sub.startswith("счёт") or "счет " in sub or "счёт " in sub:
            return "копия своего счёта"
        if "акт сверки" in sub:
            return "копия своего акта"
        return "своё письмо"
    # garbage
    junk_dom = {
        "hh.ru","site.hh.ru","aismarketing.ru","i-tenders.ru","ite.events","mail.expertgov.ru",
        "europlan.ru","expocrimea.bitrix24.ru","sro-resurs.ru","account.2gis.com","news.lemanapro.ru",
        "beget.ru","e.roseltorg.ru","rts-tender.ru","rusiranexpo.ru","dns-shop.ru",
        "inspektrum.bitrix24.ru","tehpromexport.ru","energocontinent.ru","hnyconsulting.com",
        "develop.mos.ru","list.komus.ru"
    }
    if dom in junk_dom or s.endswith(".hh.ru"):
        return "мусор"
    if dom=="gosuslugi.ru":
        return "мусор: штрафы и платные дороги"
    if dom=="pprcard.ru" and ("азс" in sub or "обслуживан" in sub):
        return "мусор"
    if dom in ("sberbank-ast.ru","saby.ru") and any(w in sub for w in ("вебинар","обучен","презентац","реестр минпромторга")):
        return "мусор"
    if dom=="saby.ru":
        return "мусор"
    if "помогу получать" in sub or "рынок" in sub and "report" in sub:
        return "мусор"
    if dom=="td166.su":
        return "мусор: чужое КП"
    # tender stream
    if dom in ("etpgpb.ru","digtp.com","lot-online.ru"):
        if "обращени" in sub:
            return "тендер: переписка по обращению"
        if "изменены условия" in sub:
            return "тендер: изменение процедуры"
        return "тендер: приглашение или дайджест"
    # admin that is real but not a sale
    if dom in ("kontur.ru",):
