    # external commercial
    if any(w in sub for w in ("запрос","заявка","кп","коммерч")):
        return "дело: запрос клиента"
    if "акт сверки" in sub:
        return "дело: акт сверки"
    if s and not s.endswith("@tonaly.ru"):
        return "дело: письмо человека"
    return "прочее"

