rows=cur.execute("""
SELECT m.date_received, a.address as sender, s.subject
FROM messages m
LEFT JOIN addresses a ON a.ROWID=m.sender
LEFT JOIN subjects s ON s.ROWID=m.subject
WHERE m.mailbox=23 AND m.date_received>=? AND IFNULL(m.deleted,0)=0
""",(cut,)).fetchall()

def stats(rows, label, weekday_only=False):
    c=Counter(); days=set(); examples=defaultdict(list)
    for r in rows:
        dt=datetime.datetime.fromtimestamp(r["date_received"], datetime.timezone.utc).astimezone(MSK)
        if weekday_only and dt.weekday()>=5:
            continue
        days.add(dt.date())
        cat=classify(r["sender"], r["subject"])
        c[cat]+=1
        if len(examples[cat])<3:
            examples[cat].append(((r["sender"] or "")[:32], (r["subject"] or "")[:70]))
    n=sum(c.values())
    nd=max(len(days),1)
    print(f"\n== {label} n={n} days={len(days)} avg={n/nd:.1f} ==")
    for k,v in c.most_common():
        print(f"  {v:4} {100*v/n:5.1f}%  {k}")
    return c,n,len(days)

cut14=datetime.datetime(2026,10,4,tzinfo=datetime.timezone.utc).timestamp()
